def format_bytes(n):
    """Return a human-readable size string, e.g. '1.5 KB'."""
    unit = 'B'
    for unit in ('B', 'KB', 'MB', 'GB', 'TB', 'PB'):
        if abs(n) < 1024.0:
            break
        n /= 1024.0
    if unit == 'B':
        return f"{int(n)} {unit}"
    return f"{n:.1f} {unit}"
